<?php
/**
 * WYMIS One-Day Intensive registration handler (Hostinger PHP mail).
 *
 * Each registration is:
 *   1. emailed to TO_EMAIL,
 *   2. confirmed to the registrant (and, for under-18 registrants, to the parent or guardian),
 *   3. saved as a row on the "Registrations" tab of the Google Sheet "WYMIS Website Inquiries".
 *
 * Event list comes from events.inc.php (generated by tools/build.py).
 * The Sheet web-app URL lives in a private file outside the public repo (same file contact.php uses).
 */
const TO_EMAIL   = 'info@wymisworks.org';
const FROM_EMAIL = 'info@wymisworks.org';
const BACK       = '/register';

$sheetFile = dirname(__DIR__) . '/wymis-sheet-url.txt';
$sheetUrl  = is_readable($sheetFile) ? trim((string)file_get_contents($sheetFile)) : '';
define('SHEET_URL', preg_match('#^https://script\.google\.com/macros/s/[\w-]+/exec$#', $sheetUrl) ? $sheetUrl : '');

date_default_timezone_set('America/Phoenix');
$EVENTS = include __DIR__ . '/events.inc.php';

function back($q) { header('Location: ' . BACK . '?' . $q . '#register', true, 303); exit; }
function clean($v, $max) {
    $v = trim((string)($v ?? ''));
    $v = str_replace(["\r", "\n", "%0a", "%0d"], ' ', $v);
    return mb_substr(strip_tags($v), 0, $max);
}
function utf8_subject($s) { return '=?UTF-8?B?' . base64_encode($s) . '?='; }
function send($to, $subject, $body, $replyTo) {
    $h  = 'From: WYMIS <' . FROM_EMAIL . ">\r\n";
    $h .= 'Reply-To: ' . $replyTo . "\r\n";
    $h .= "MIME-Version: 1.0\r\nContent-Type: text/plain; charset=UTF-8\r\n";
    return @mail($to, utf8_subject($subject), $body, $h, '-f' . FROM_EMAIL);
}

if ($_SERVER['REQUEST_METHOD'] !== 'POST') { back('error=1'); }
if (!empty($_POST['website'])) { back('registered=1'); }   // honeypot

$event   = clean($_POST['event'] ?? '', 60);
$first   = clean($_POST['first'] ?? '', 80);
$last    = clean($_POST['last'] ?? '', 80);
$email   = clean($_POST['email'] ?? '', 160);
$phone   = clean($_POST['phone'] ?? '', 40);
$age     = clean($_POST['age'] ?? '', 20);
$org     = clean($_POST['org'] ?? '', 160);
$heard   = clean($_POST['heard'] ?? '', 80);
$gname   = clean($_POST['gname'] ?? '', 120);
$gemail  = clean($_POST['gemail'] ?? '', 160);
$gphone  = clean($_POST['gphone'] ?? '', 40);
$consent = ($_POST['gconsent'] ?? '') === 'yes';
$notes   = mb_substr(strip_tags(trim((string)($_POST['notes'] ?? ''))), 0, 2000);
$ip      = $_SERVER['REMOTE_ADDR'] ?? '';

$ages  = ['16 or 17', '18 to 21', '22 to 26', '27 or older'];
$minor = ($age === '16 or 17');

if (!isset($EVENTS[$event]) || $first === '' || $last === '' || !filter_var($email, FILTER_VALIDATE_EMAIL) || !in_array($age, $ages, true)) {
    back('error=1');
}
if ($minor && ($gname === '' || !filter_var($gemail, FILTER_VALIDATE_EMAIL) || !$consent)) {
    back('error=3');
}
if (!$minor) { $gname = $gemail = $gphone = ''; $consent = false; }

[$city, $day, $iso, $where] = $EVENTS[$event];
$perk = $EVENTS[$event][4] ?? '';
if ($iso < date('Y-m-d')) { back('error=4'); }   // past date

// Light rate limit: one registration per IP every 30 seconds
$ipKey = sys_get_temp_dir() . '/wymis_reg_' . md5($ip ?: 'x');
if (file_exists($ipKey) && time() - filemtime($ipKey) < 30) { back('registered=' . rawurlencode($event)); }
@touch($ipKey);

$received = date('Y-m-d g:i A');
$name = "$first $last";

// 1. Notice to the WYMIS inbox
$b  = "New One-Day Intensive registration\n\n";
$b .= "Event: $city, $day\nLocation: $where\n\n";
$b .= "Name: $name\nEmail: $email\nPhone: $phone\nAge: $age\nSchool or organization: $org\nHeard about WYMIS: $heard\n";
if ($minor) { $b .= "\nParent or guardian: $gname\nParent email: $gemail\nParent phone: $gphone\nPermission confirmed: Yes\n"; }
$b .= "\nAccessibility needs or questions:\n$notes\n\nReceived: $received (Phoenix time)\nIP: $ip\n";
$notice = send(TO_EMAIL, "WYMIS registration: $name ($city, " . date('M j', strtotime($iso)) . ")", $b, "$name <$email>");

// 2. Confirmation to the registrant (and parent or guardian)
$c  = "Hi $first,\n\n";
$c .= "You are registered for the free WYMIS One-Day Intensive.\n\n";
$c .= "City: $city\nDate: $day\nTime: 9:00 AM to 6:00 PM local time (check-in opens at 8:30 AM)\nLocation: $where\n\n";
$c .= (strpos($where, 'to be announced') !== false)
    ? "We will email you the venue address as soon as it is confirmed.\n\n"
    : "Please arrive a few minutes early so we can start on time.\n\n";
if ($perk !== '') { $c .= "$perk\n\n"; }
$c .= "What to bring: a notebook or device for notes. We will share lunch details before the day.\n";
$c .= "See the day's schedule: https://wymisworks.org/intensive\n\n";
$c .= "Can't make it anymore? Just reply to this email so we can give your seat to someone else.\n\n";
$c .= "WYMIS (What You Missed In School)\nhttps://wymisworks.org\n";
$c .= "A program under the umbrella of Love Nation Ministries, a registered 501(c)(3) nonprofit organization.\n";
$confirm = send($email, "You're registered: WYMIS One-Day Intensive, $city", $c, 'WYMIS <' . FROM_EMAIL . '>');

$gconfirm = false;
if ($minor) {
    $g  = "Hi $gname,\n\n";
    $g .= "$first $last registered for the free WYMIS One-Day Intensive and listed you as their parent or guardian, confirming you gave permission to attend.\n\n";
    $g .= "City: $city\nDate: $day\nTime: 9:00 AM to 6:00 PM local time (check-in opens at 8:30 AM)\nLocation: $where\n\n";
    $g .= "WYMIS is a workforce readiness and life skills program for ages 16 to 26. The day covers soft skills, networking, financial literacy, business basics, etiquette, and branding with AI and technology.\n";
    $g .= "Program details: https://wymisworks.org/intensive\n\n";
    $g .= "If you did not give permission, or have questions, please reply to this email.\n\n";
    $g .= "WYMIS\nhttps://wymisworks.org\n";
    $gconfirm = send($gemail, "Your child is registered: WYMIS One-Day Intensive, $city", $g, 'WYMIS <' . FROM_EMAIL . '>');
}

// 3. Backup row in the Google Sheet ("Registrations" tab)
$logged = false;
if (SHEET_URL !== '' && function_exists('curl_init')) {
    $payload = json_encode([
        'source' => 'wymisworks.org', 'form' => 'registration', 'received' => $received,
        'event' => $city, 'date' => $day, 'location' => $where,
        'first' => $first, 'last' => $last, 'email' => $email, 'phone' => $phone, 'age' => $age, 'org' => $org, 'heard' => $heard,
        'gname' => $gname, 'gemail' => $gemail, 'gphone' => $gphone, 'gconsent' => $consent,
        'notes' => $notes, 'notice' => $notice, 'confirmation' => $confirm, 'gconfirmation' => $gconfirm, 'ip' => $ip,
    ]);
    $ch = curl_init(SHEET_URL);
    curl_setopt_array($ch, [
        CURLOPT_POST => true, CURLOPT_POSTFIELDS => $payload,
        CURLOPT_HTTPHEADER => ['Content-Type: application/json'],
        CURLOPT_RETURNTRANSFER => true, CURLOPT_FOLLOWLOCATION => true,
        CURLOPT_CONNECTTIMEOUT => 5, CURLOPT_TIMEOUT => 10,
    ]);
    $resp = curl_exec($ch);
    curl_close($ch);
    $logged = is_string($resp) && strpos($resp, '"ok":true') !== false;
}

back(($notice || $logged) ? 'registered=' . rawurlencode($event) : 'error=2');
